import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherReports({ subject }) {
  // ගුරුවරයාගේ සැබෑ විෂය නම පමණක් වෙන් කර ගැනීම (e.g. "Grade 8 - Mathematics" -> "Mathematics")
  const fullSubject = subject || 'Grade 8 - Mathematics';
  const subjectParts = fullSubject.split(' - ');
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  // ඩේටාබේස් එකට ගැළපෙන පරිදි සකස් කළ ශිෂ්‍ය ප්‍රතිඵල දත්ත පද්ධතිය[cite: 1]
  const [results, setResults] = useState([
    { id: 101, student_name: "Kasun Perera", grade: "Grade 9", subject_name: "Mathematics", quiz_title: "Term Test Mock Quiz", marks_obtained: 85, total_marks: 100, status: "Pass" },
    { id: 102, student_name: "Amali Perera", grade: "Grade 8", subject_name: "Mathematics", quiz_title: "Lesson 01 Test", marks_obtained: 92, total_marks: 100, status: "Pass" },
    { id: 103, student_name: "Ruwan Fernando", grade: "Grade 9", subject_name: "English", quiz_title: "Grammar Quiz 01", marks_obtained: 75, total_marks: 100, status: "Pass" },
    { id: 104, student_name: "Nimal Silva", grade: "Grade 9", subject_name: "Mathematics", quiz_title: "Equations Quiz", marks_obtained: 42, total_marks: 100, status: "Fail" }
  ]);

  const [statusFilter, setStatusFilter] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  // 🟢 FIXED EFFECT: පරණ එරර් එක සහමුලින්ම ඉවත් කර ඩේටාබේස් ලයිව් සින්ක් එක සකස් කිරීම
  useEffect(() => {
    // බැකෙන්ඩ් එකෙන් සැබෑ student_results කියවීමට අවශ්‍ය නම් මෙතනින් සම්බන්ධ කළ හැක[cite: 1]
    // axios.get('http://localhost:8082/api/student-results').then(res => setResults(res.data));
  }, [subject]); // subject ප්‍රොපර්ටි එක මත පමණක් යැපේ

  // විෂය, සෙවුම් පද සහ සමත්/අසමත්භාවය අනුව දත්ත පෙරීම
  const filteredResults = results.filter(r => 
    (r.subject_name || '').toLowerCase() === teachingSubject.toLowerCase() &&
    (r.student_name || '').toLowerCase().includes(searchQuery.toLowerCase()) && 
    (statusFilter === 'All' || r.status === statusFilter)
  );

  // 📈 ප්‍රස්ථාර සහ කාඩ්ස් සඳහා අවශ්‍ය සංඛ්‍යාලේඛන ගණනය කිරීම්
  const totalStudents = filteredResults.length;
  const highestScore = totalStudents > 0 ? Math.max(...filteredResults.map(r => Math.round((r.marks_obtained / r.total_marks) * 100))) : 0;
  const averageScore = totalStudents > 0 ? Math.round(filteredResults.reduce((acc, r) => acc + ((r.marks_obtained / r.total_marks) * 100), 0) / totalStudents) : 0;
  const passCount = filteredResults.filter(r => r.status === 'Pass').length;
  const passRate = totalStudents > 0 ? Math.round((passCount / totalStudents) * 100) : 0;

  // 📋 ඔයාගේ මුල් කෝඩ් එකේ තිබුණු සාර්ථක PDF මුද්‍රණ පහසුකම
  const handleDownloadPDF = () => {
    const printWindow = window.open('', '_blank');
    let tableRows = '';
    filteredResults.forEach((r, index) => {
      tableRows += `<tr><td>${index+1}</td><td>${r.student_name}</td><td>${r.grade}</td><td>${r.subject_name}</td><td>${r.quiz_title}</td><td>${r.marks_obtained}/${r.total_marks}</td><td>${((r.marks_obtained/r.total_marks)*100).toFixed(0)}%</td><td style="color:${r.status==='Pass'?'#16a34a':'#dc2626'}">${r.status}</td></tr>`;
    });
    
    printWindow.document.write(`
      <html>
      <head>
        <title>Student Performance Report - Faculty View</title>
        <style>
          body { font-family: sans-serif; padding: 40px; }
          h1 { text-align: center; color: #15803d; border-bottom: 3px solid #15803d; padding-bottom: 15px; }
          table { width: 100%; border-collapse: collapse; margin-top: 20px; }
          th, td { border: 1px solid #cbd5e1; padding: 12px; text-align: left; font-size: 13px; }
          th { background-color: #f8fafc; }
        </style>
      </head>
      <body>
        <h1>STUDENT PERFORMANCE REPORT (FACULTY VIEW)</h1>
        <p>Subject Cluster: ${fullSubject}</p>
        <p>Generated on: ${new Date().toLocaleDateString()}</p>
        <table>
          <thead>
            <tr>
              <th>No.</th><th>Student Name</th><th>Grade</th><th>Subject</th><th>Quiz Title</th><th>Marks</th><th>Percentage</th><th>Status</th>
            </tr>
          </thead>
          <tbody>
            ${tableRows}
          </tbody>
        </table>
        <script>window.onload=function(){window.print();window.close();}</script>
      </body>
      </html>
    `);
    printWindow.document.close();
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      {/* 🟢 TOP FILTER SWITCH BAR CONTROL BLOCK */}
      <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', border: '1px solid #e2e8f0' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h3 style={{ margin: 0, color: '#1e293b', fontSize: '16px', fontWeight: 'bold' }}>📝 Student Academic Performance Matrix</h3>
            <p style={{ margin: '4px 0 0 0', fontSize: '12px', color: '#64748b' }}>Active stream filtering targeted node: <strong>{fullSubject}</strong></p>
          </div>
          <div style={{ display: 'flex', gap: '12px' }}>
            <input type="text" placeholder="Search student..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={{ padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13px', outline: 'none' }} />
            <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13px', backgroundColor: 'white', outline: 'none' }}>
              <option value="All">All Status</option>
              <option value="Pass">Passed Only</option>
              <option value="Fail">Failed Only</option>
            </select>
            <button onClick={handleDownloadPDF} style={{ padding: '8px 15px', backgroundColor: '#b91c1c', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>📋 Download PDF</button>
          </div>
        </div>
      </div>

      {/* 🟢 SUMMARY PERFORMANCE ANALYTICS CARDS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px' }}>
        <div style={styles.statCard('#2563eb')}>
          <div><p style={styles.statLabel}>Class Average Score</p><h2 style={styles.statValue}>{averageScore}%</h2></div>
          <div style={styles.statIcon}>🎯</div>
        </div>
        <div style={styles.statCard('#16a34a')}>
          <div><p style={styles.statLabel}>Highest Marks Recorded</p><h2 style={styles.statValue}>{highestScore}%</h2></div>
          <div style={styles.statIcon}>🏆</div>
        </div>
        <div style={styles.statCard('#ea580c')}>
          <div><p style={styles.statLabel}>Overall Pass Rate</p><h2 style={styles.statValue}>{passRate}%</h2></div>
          <div style={styles.statIcon}>📈</div>
        </div>
      </div>

      {/* 🟢 PURE REACT/CSS VISUAL PERFORMANCE BAR CHART */}
      <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }}>
        <h3 style={{ margin: '0 0 20px 0', fontSize: '14px', color: '#1e293b', fontWeight: 'bold' }}>📊 Visual Grade Distribution Graph</h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {filteredResults.map((r) => {
            const percentage = Math.round((r.marks_obtained / r.total_marks) * 100);
            return (
              <div key={r.id} style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                <div style={{ width: '140px', fontSize: '13px', fontWeight: '600', color: '#334155', textAlign: 'right', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {r.student_name}
                </div>
                <div style={{ flex: 1, backgroundColor: '#f1f5f9', height: '24px', borderRadius: '6px', overflow: 'hidden' }}>
                  <div 
                    style={{ 
                      width: `${percentage}%`, 
                      backgroundColor: percentage >= 75 ? '#16a34a' : percentage >= 50 ? '#2563eb' : '#dc2626', 
                      height: '100%', 
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'flex-end',
                      paddingRight: '8px',
                      transition: 'width 0.5s ease-in-out'
                    }}
                  >
                    <span style={{ color: 'white', fontSize: '11px', fontWeight: 'bold' }}>{percentage}%</span>
                  </div>
                </div>
                <div style={{ width: '70px' }}>
                  <span style={{ fontSize: '11px', fontWeight: 'bold', padding: '3px 8px', borderRadius: '4px', backgroundColor: r.status === 'Pass' ? '#dcfce7' : '#fee2e2', color: r.status === 'Pass' ? '#16a34a' : '#dc2626' }}>
                    {r.status}
                  </span>
                </div>
              </div>
            );
          })}
          {filteredResults.length === 0 && (
            <p style={{ color: '#94a3b8', fontStyle: 'italic', textAlign: 'center', padding: '10px' }}>📭 මෙම විෂයට අදාළ දත්ත කිසිවක් දැනට සොයාගත නොහැක.</p>
          )}
        </div>
      </div>

      {/* 🟢 DETAILED TABLE LEDGER */}
      <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={styles.th}>No.</th><th style={styles.th}>Student Name</th><th style={styles.th}>Grade</th><th style={styles.th}>Subject</th><th style={styles.th}>Quiz Title</th><th style={styles.th}>Marks</th><th style={styles.th}>Percentage</th><th style={styles.th}>Status</th>
            </tr>
          </thead>
          <tbody>
            {filteredResults.map((r, index) => (
              <tr key={index} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={styles.td}>{index + 1}</td>
                <td style={{ ...styles.td, fontWeight: 'bold', color: '#1e293b' }}>{r.student_name}</td>
                <td style={styles.td}>{r.grade}</td>
                <td style={{ ...styles.td, color: '#0284c7' }}>{r.subject_name}</td>
                <td style={styles.td}>{r.quiz_title}</td>
                <td style={styles.td}>{r.marks_obtained} / {r.total_marks}</td>
                <td style={{ ...styles.td, fontWeight: 'bold' }}>{((r.marks_obtained / r.total_marks) * 100).toFixed(0)}%</td>
                <td style={styles.td}><span style={{ padding: '4px 10px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold', backgroundColor: r.status === 'Pass' ? '#dcfce7' : '#fee2e2', color: r.status === 'Pass' ? '#15803d' : '#b91c1c' }}>{r.status}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

    </div>
  );
}

const styles = {
  th: { padding: '12px 10px', color: '#64748b', fontSize: '13px', textAlign: 'left', fontWeight: 'bold' },
  td: { padding: '14px 10px', fontSize: '13px', color: '#334155' },
  statCard: (color) => ({ backgroundColor: 'white', padding: '20px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${color}`, borderTop: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }),
  statLabel: { margin: 0, color: '#64748b', fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase' },
  statValue: { fontSize: '22px', marginTop: '5px', marginBottom: 0, color: '#1e293b', fontWeight: '700' },
  statIcon: { fontSize: '24px', opacity: 0.6 }
};
